## Advanced Bit Manipulation

### Reverse Bits

#### C++ Implementation
```cpp
uint32_t reverseBits(uint32_t n) {
    uint32_t result = 0;
    for (int i = 0; i < 32; i++) {
        result <<= 1;
        result |= (n & 1);
        n >>= 1;
    }
    return result;
}
```

### Number of 1 Bits

#### C++ Implementation
```cpp
int hammingWeight(uint32_t n) {
    int count = 0;
    while (n) {
        count += (n & 1);
        n >>= 1;
    }
    return count;
}
```

### Power of Four

#### C++ Implementation
```cpp
bool isPowerOfFour(int n) {
    return n > 0 && (n & (n - 1)) == 0 && (n & 0xAAAAAAAA) == 0;
}
```

**Explanation:** Power of 4 must be power of 2 AND bit must be at even position (0xAAAAAAAA has bits at odd positions).

### Maximum XOR of Two Numbers in Array

#### C++ Implementation (Trie-based)
```cpp
class TrieNode {
public:
    TrieNode* children[2];
    TrieNode() {
        children[0] = children[1] = nullptr;
    }
};

class Trie {
private:
    TrieNode* root;

public:
    Trie() {
        root = new TrieNode();
    }

    void insert(int num) {
        TrieNode* node = root;
        for (int i = 31; i >= 0; i--) {
            int bit = (num >> i) & 1;
            if (node->children[bit] == nullptr) {
                node->children[bit] = new TrieNode();
            }
            node = node->children[bit];
        }
    }

    int findMaxXOR(int num) {
        TrieNode* node = root;
        int maxXOR = 0;

        for (int i = 31; i >= 0; i--) {
            int bit = (num >> i) & 1;
            int oppositeBit = 1 - bit;

            if (node->children[oppositeBit] != nullptr) {
                maxXOR |= (1 << i);
                node = node->children[oppositeBit];
            } else {
                node = node->children[bit];
            }
        }

        return maxXOR;
    }
};

int findMaximumXOR(vector<int>& nums) {
    Trie trie;
    int maxXOR = 0;

    for (int num : nums) {
        trie.insert(num);
        maxXOR = max(maxXOR, trie.findMaxXOR(num));
    }

    return maxXOR;
}
```

