## Shortest Path Algorithms

### Dijkstra's Algorithm
Finds shortest path from source to all vertices in weighted graph (non-negative weights).

**Time Complexity:** O((V + E) log V) with priority queue

#### C++ Implementation
```cpp
#include <bits/stdc++.h>
using namespace std;

vector<int> dijkstra(vector<vector<pair<int, int>>>& graph, int start) {
    int n = graph.size();
    vector<int> distance(n, INT_MAX);
    priority_queue<pair<int, int>, vector<pair<int, int>>, 
                   greater<pair<int, int>>> pq;

    distance[start] = 0;
    pq.push({0, start});

    while (!pq.empty()) {
        int dist = pq.top().first;
        int node = pq.top().second;
        pq.pop();

        if (dist > distance[node]) continue;

        for (auto [neighbor, weight] : graph[node]) {
            int newDist = dist + weight;
            if (newDist < distance[neighbor]) {
                distance[neighbor] = newDist;
                pq.push({newDist, neighbor});
            }
        }
    }

    return distance;
}
```

#### Python Implementation
```python
import heapq

def dijkstra(graph, start):
    n = len(graph)
    distance = [float('inf')] * n
    pq = [(0, start)]
    distance[start] = 0

    while pq:
        dist, node = heapq.heappop(pq)

        if dist > distance[node]:
            continue

        for neighbor, weight in graph[node]:
            new_dist = dist + weight
            if new_dist < distance[neighbor]:
                distance[neighbor] = new_dist
                heapq.heappush(pq, (new_dist, neighbor))

    return distance
```

### Bellman-Ford Algorithm
Finds shortest path allowing negative weights, detects negative cycles.

**Time Complexity:** O(V × E)

#### C++ Implementation
```cpp
#include <bits/stdc++.h>
using namespace std;

vector<int> bellmanFord(vector<vector<pair<int, int>>>& edges, int n, int start) {
    vector<int> distance(n, INT_MAX);
    distance[start] = 0;

    // Relax edges V-1 times
    for (int i = 0; i < n - 1; i++) {
        for (auto [u, v, w] : edges) {
            if (distance[u] != INT_MAX && distance[u] + w < distance[v]) {
                distance[v] = distance[u] + w;
            }
        }
    }

    // Check for negative cycles
    for (auto [u, v, w] : edges) {
        if (distance[u] != INT_MAX && distance[u] + w < distance[v]) {
            // Negative cycle detected
            return {};
        }
    }

    return distance;
}
```

### Floyd-Warshall Algorithm
Finds shortest path between all pairs of vertices.

**Time Complexity:** O(V³)

#### C++ Implementation
```cpp
#include <bits/stdc++.h>
using namespace std;

vector<vector<int>> floydWarshall(vector<vector<int>>& graph) {
    int n = graph.size();
    vector<vector<int>> dist = graph;

    for (int k = 0; k < n; k++) {
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (dist[i][k] != INT_MAX && dist[k][j] != INT_MAX) {
                    dist[i][j] = min(dist[i][j], dist[i][k] + dist[k][j]);
                }
            }
        }
    }

    return dist;
}
```

#### Python Implementation
```python
def floyd_warshall(graph):
    n = len(graph)
    dist = [row[:] for row in graph]

    for k in range(n):
        for i in range(n):
            for j in range(n):
                if dist[i][k] != float('inf') and dist[k][j] != float('inf'):
                    dist[i][j] = min(dist[i][j], dist[i][k] + dist[k][j])

    return dist
```

