## Minimum Spanning Tree (MST)

### Kruskal's Algorithm
Uses Union-Find (DSU) to build MST by adding edges in increasing weight order.

**Time Complexity:** O(E log E)

#### C++ Implementation
```cpp
#include <bits/stdc++.h>
using namespace std;

class DSU {
    vector<int> parent, rank;
public:
    DSU(int n) : parent(n), rank(n, 0) {
        iota(parent.begin(), parent.end(), 0);
    }

    int find(int x) {
        if (parent[x] != x) {
            parent[x] = find(parent[x]);
        }
        return parent[x];
    }

    bool unite(int x, int y) {
        int px = find(x), py = find(y);
        if (px == py) return false;

        if (rank[px] < rank[py]) swap(px, py);
        parent[py] = px;
        if (rank[px] == rank[py]) rank[px]++;
        return true;
    }
};

int kruskal(vector<vector<int>>& edges, int n) {
    sort(edges.begin(), edges.end(), 
         [](const vector<int>& a, const vector<int>& b) {
             return a[2] < b[2];
         });

    DSU dsu(n);
    int mstWeight = 0;

    for (auto& edge : edges) {
        int u = edge[0], v = edge[1], w = edge[2];
        if (dsu.unite(u, v)) {
            mstWeight += w;
        }
    }

    return mstWeight;
}
```

### Prim's Algorithm
Grows MST from a starting vertex, uses priority queue.

**Time Complexity:** O(E log V)

#### C++ Implementation
```cpp
#include <bits/stdc++.h>
using namespace std;

int prim(vector<vector<pair<int, int>>>& graph, int start) {
    int n = graph.size();
    vector<bool> inMST(n, false);
    priority_queue<pair<int, int>, vector<pair<int, int>>, 
                   greater<pair<int, int>>> pq;

    int mstWeight = 0;
    pq.push({0, start});

    while (!pq.empty()) {
        int weight = pq.top().first;
        int node = pq.top().second;
        pq.pop();

        if (inMST[node]) continue;

        inMST[node] = true;
        mstWeight += weight;

        for (auto [neighbor, w] : graph[node]) {
            if (!inMST[neighbor]) {
                pq.push({w, neighbor});
            }
        }
    }

    return mstWeight;
}
```

#### Python Implementation
```python
import heapq

def prim(graph, start):
    n = len(graph)
    in_mst = [False] * n
    pq = [(0, start)]
    mst_weight = 0

    while pq:
        weight, node = heapq.heappop(pq)

        if in_mst[node]:
            continue

        in_mst[node] = True
        mst_weight += weight

        for neighbor, w in graph[node]:
            if not in_mst[neighbor]:
                heapq.heappush(pq, (w, neighbor))

    return mst_weight
```

