int atMostKDistinct(string s, int k) {
    unordered_map<char, int> freq;
    int left = 0;
    int count = 0;

    for (int right = 0; right < s.length(); right++) {
        freq[s[right]]++;

        while (freq.size() > k) {
            freq[s[left]]--;
            if (freq[s[left]] == 0) {
                freq.erase(s[left]);
