## KMP Algorithm (Knuth-Morris-Pratt)

Efficient pattern matching algorithm using failure function (LPS array).

### Understanding LPS (Longest Proper Prefix which is also Suffix)

#### C++ Implementation
```cpp
#include <bits/stdc++.h>
using namespace std;

// Build LPS array
vector<int> buildLPS(string pattern) {
    int m = pattern.length();
    vector<int> lps(m, 0);
    int len = 0;
    int i = 1;

    while (i < m) {
        if (pattern[i] == pattern[len]) {
            len++;
            lps[i] = len;
            i++;
        } else {
            if (len != 0) {
                len = lps[len - 1];
            } else {
                lps[i] = 0;
                i++;
            }
        }
    }

    return lps;
}

// KMP Search
vector<int> kmpSearch(string text, string pattern) {
    vector<int> result;
    vector<int> lps = buildLPS(pattern);

    int n = text.length();
    int m = pattern.length();
    int i = 0, j = 0;  // i for text, j for pattern

    while (i < n) {
        if (text[i] == pattern[j]) {
            i++;
            j++;
        }

        if (j == m) {
            result.push_back(i - j);  // Found at index i - j
            j = lps[j - 1];
        } else if (i < n && text[i] != pattern[j]) {
            if (j != 0) {
                j = lps[j - 1];
            } else {
                i++;
            }
        }
    }

    return result;
}
```

#### Python Implementation
```python
def build_lps(pattern):
    m = len(pattern)
    lps = [0] * m
    length = 0
    i = 1

    while i < m:
        if pattern[i] == pattern[length]:
            length += 1
            lps[i] = length
            i += 1
        else:
            if length != 0:
                length = lps[length - 1]
            else:
                lps[i] = 0
                i += 1

    return lps

def kmp_search(text, pattern):
    result = []
    lps = build_lps(pattern)

    n, m = len(text), len(pattern)
    i = j = 0  # i for text, j for pattern

    while i < n:
        if text[i] == pattern[j]:
            i += 1
            j += 1

        if j == m:
            result.append(i - j)  # Found at index i - j
            j = lps[j - 1]
        elif i < n and text[i] != pattern[j]:
            if j != 0:
                j = lps[j - 1]
            else:
                i += 1

    return result
```

**Time Complexity:** O(n + m)  
**Space Complexity:** O(m)

