## String Manipulation

### Reverse Words in String

#### C++ Implementation
```cpp
string reverseWords(string s) {
    // Remove extra spaces
    string cleaned;
    for (int i = 0; i < s.length(); i++) {
        if (s[i] != ' ' || (i > 0 && s[i-1] != ' ')) {
            cleaned += s[i];
        }
    }

    // Trim leading/trailing spaces
    if (cleaned[0] == ' ') cleaned = cleaned.substr(1);
    if (cleaned.back() == ' ') cleaned.pop_back();

    // Reverse entire string
    reverse(cleaned.begin(), cleaned.end());

    // Reverse each word
    int start = 0;
    for (int i = 0; i <= cleaned.length(); i++) {
        if (i == cleaned.length() || cleaned[i] == ' ') {
            reverse(cleaned.begin() + start, cleaned.begin() + i);
            start = i + 1;
        }
    }

    return cleaned;
}
```

### Valid Parentheses

#### C++ Implementation (Using Stack)
```cpp
bool isValid(string s) {
    stack<char> st;
    unordered_map<char, char> mapping = {
        {')', '('},
        {'}', '{'},
        {']', '['}
    };

    for (char ch : s) {
        if (mapping.find(ch) != mapping.end()) {
            if (st.empty() || st.top() != mapping[ch]) {
                return false;
            }
            st.pop();
        } else {
            st.push(ch);
        }
    }

    return st.empty();
}
```

