void twoPointersSame(vector<int>& nums) {
    int slow = 0;
    int fast = 0;

    while (fast < nums.size()) {
        if (condition) {
            nums[slow] = nums[fast];
            slow++;
        }
        fast++;
    }

    return slow;  // New length
}
